// Construye un resumen del día por tenant y lo envía al WhatsApp del negocio.
const { items } = $input.first().json;
const out = [];

for (const block of items || []) {
  const lines = [`Agenda de hoy (${block.date_local}):`];
  for (const barber of block.barbers) {
    if (barber.appointments.length === 0) {
      lines.push(`${barber.name}: sin turnos.`);
      continue;
    }
    lines.push(`${barber.name} (${barber.appointments.length} turnos):`);
    for (const appt of barber.appointments) {
      lines.push(`  ${appt.time_local} #${appt.daily_number} ${appt.customer_name} — ${appt.services.join(', ')}`);
    }
  }
  out.push({
    json: {
      waPayload: {
        messaging_product: 'whatsapp',
        to: block.tenant.whatsapp_number,
        type: 'template',
        template: {
          name: 'notificacion_interna',
          language: { code: 'es_CO' },
          components: [
            { type: 'body', parameters: [{ type: 'text', text: lines.join(' | ') }] },
          ],
        },
      },
    },
  });
}

return out;
